// ------------------------------------------------------------------- proceso

const datosRuta = process.argv.slice(2).find(a => a.endsWith('.json')) || path.join(AQUI, 'datos.json');
if (!fs.existsSync(datosRuta)) { console.error(`No encuentro ${datosRuta}`); process.exit(1); }
const datos = JSON.parse(fs.readFileSync(datosRuta, 'utf8'));
const CREATIVOS = Array.isArray(datos) ? datos : datos.creativos;

fs.mkdirSync(SALIDA, { recursive: true });
fs.mkdirSync(HTMLDIR, { recursive: true });

let errores = 0;
const indice = [];
for (const f of CREATIVOS) {
  const S = SISTEMAS[ALIAS[sinTildes(f.sistema)] ?? f.sistema];
  const fallos = [];
  if (!S) fallos.push(`sistema desconocido "${f.sistema}" (hay: ${Object.keys(ALIAS).join(', ')})`);
  let rutaFoto = null;
  try {
    rutaFoto = f.foto ? await resolverFoto(f.foto) : null;
    if (!rutaFoto || !fs.existsSync(rutaFoto)) fallos.push(`falta la foto ${f.foto}`);
  } catch (e) { fallos.push(`no pude traer la foto ${f.foto}: ${e.message}`); }
  const textos = [f.titular, f.sub, f.sub2, f.arriba, f.destacado, f.cierre, f.items, f.grande];
  if (f.anuncio) textos.push(f.anuncio.titular, f.anuncio.texto);
  for (const q of textosProhibidos(textos)) fallos.push(`el texto trae ${q}`);
  let deducida = null;
  if (f.anuncio && f.categoria) {
    deducida = categoriaDeducida(f.anuncio);
    if (deducida !== f.categoria) fallos.push(`el CRM deduciría "${deducida}" y no "${f.categoria}"`);
  }
  if (fallos.length) { errores++; console.log(`RECHAZADO ${f.id}: ${fallos.join(' | ')}`); continue; }

  const dim = medir(rutaFoto);
  f._url = 'file:///' + rutaFoto.split(String.fromCharCode(92)).join('/');
  const caja = S.caja(f);
  const recorte = f.recorte || [0, 0, 1, 1];
  const banda = (S.banda ? S.banda(f) : { arriba: 0, abajo: S.alto });
  const pos = componer(dim, recorte, caja, f, banda);
  const cfg = S.cfg(f);
  // El rostro declarado sobre la FOTO manda sobre el declarado en píxeles del
  // lienzo, que es el que se quedaba viejo en cuanto cambiaba el encuadre.
  if (Array.isArray(f.cara)) cfg.rostroDeclarado = proyectar(f.cara, pos, caja);
  cfg.sujetoPx = pos.sujeto ?? null;
  cfg.banda = banda;
  const html = `<!doctype html><html lang="es"><head>${CABEZA(f.id)}
${S.html(f, pos)}
${ANALISIS(pos, caja, S.ancho, S.alto, cfg)}
</body></html>`;

  const ruta = path.join(HTMLDIR, f.id + '.html');
  fs.writeFileSync(ruta, html, 'utf8');
  const url = 'file:///' + ruta.replace(/\\/g, '/');
  const comunes = ['--headless=new', '--disable-gpu', '--hide-scrollbars',
    '--allow-file-access-from-files', '--force-device-scale-factor=1',
    '--window-size=' + S.ancho + ',' + S.alto, '--virtual-time-budget=15000'];

  const dom = execFileSync(CHROME, [...comunes, '--dump-dom', url], { encoding: 'utf8' });
  const titulo = (dom.match(/<title>([^<]*)<\/title>/) || [, ''])[1];
  if (titulo.startsWith('ERROR')) { errores++; console.log(`RECHAZADO ${f.id}: ${titulo}`); continue; }
  const dato = k => (titulo.match(new RegExp('\\b' + k + '=([^\\s]+)')) || [, ''])[1];
  const aviso = [];
  if (titulo.startsWith('FALTAN')) aviso.push(`no cargaron tipografías: ${titulo.slice(7, titulo.indexOf(']'))}`);
  if ((dato('movidos') || '').includes('IMPOSIBLE')) {
    aviso.push('el texto tapa la cara y no hay dónde moverlo: cambia "encuadre" o el recorte');
  }
  const origen = dato('origenrostro');
  if (origen === 'declarado-DUDOSO') {
    errores++;
    console.log(`RECHAZADO ${f.id}: la zona de rostro declarada no contiene piel; está mal leída`);
    continue;
  }
  if (origen === 'sin-verificar') {
    console.log(`  aviso ${f.id}: no detecté ningún rostro; declara "rostro":[x0,y0,x1,y1] o "rostro":false si no aplica`);
  }
  const medidas = {};
  for (const z of cfg.zonas) {
    const m = titulo.match(new RegExp('\\b' + z.nombre + '=([\\d.]+)/(-?\\d+)-(-?\\d+)'));
    if (!m) { aviso.push(`no pude medir la zona ${z.nombre}`); continue; }
    medidas[z.nombre] = { contraste: Number(m[1]), arriba: +m[2], abajo: +m[3] };
    if (Number(m[1]) < (f.contrasteMinimo ?? 4.5)) aviso.push(`"${z.nombre}" se lee a ${m[1]}:1 en su peor decil`);
    if (+m[3] > S.alto - 20 || +m[2] < 0) aviso.push(`"${z.nombre}" se sale del lienzo (${m[2]}-${m[3]})`);
  }
  if (aviso.length) { errores++; console.log(`RECHAZADO ${f.id}: ${aviso.join(' | ')}`); continue; }

  execFileSync(CHROME, [...comunes, '--screenshot=' + path.join(SALIDA, f.id + '.png'), url], { stdio: 'ignore' });
  indice.push({
    archivo: f.id + '.png', sistema: f.sistema, categoria: f.categoria ?? null,
    foto: f.foto, original: `${dim.w}x${dim.h}`, ampliacion: pos.ampliacion,
    fondo: dato('fondo'), acento: dato('acento'), acento_texto: dato('acentotexto'), rostro: dato('rostro'), origen_rostro: dato('origenrostro'),
    movidos: dato('movidos') || null, medidas, caduca_con: f.mes ?? null,
    anuncio_titular: f.anuncio?.titular ?? null, anuncio_texto: f.anuncio?.texto ?? null,
    categoria_que_deduce_el_crm: deducida,
  });
  const detalle = Object.entries(medidas).map(([k, v]) => `${k} ${v.contraste}:1`).join('  ');
  console.log(`generado ${f.id}.png  [${f.sistema}]  fondo ${dato('fondo')}  acento ${dato('acento')}  rostro ${dato('rostro')}  ${detalle}`);
}

fs.writeFileSync(path.join(SALIDA, 'copys.json'), JSON.stringify(indice, null, 2), 'utf8');
console.log(`\n${indice.length} flyers en ${SALIDA}`);
if (errores) { console.log(`${errores} rechazados`); process.exitCode = 1; }

