// Guarda esto como extraer.mjs junto al JSON y corre: node extraer.mjs DCARELA_KIT_FLYERS_v2.json
import fs from 'node:fs'; import path from 'node:path'; import crypto from 'node:crypto';
const kit = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
for (const d of ['tipografias', 'fotos', 'referencias', 'salida']) fs.mkdirSync(d, { recursive: true });
const sacar = (r, dir) => {
  const b = Buffer.from(r.base64, 'base64');
  const ok = crypto.createHash('sha256').update(b).digest('hex') === r.sha256;
  fs.writeFileSync(path.join(dir, r.archivo), b);
  console.log((ok ? 'ok  ' : 'SHA NO COINCIDE ') + dir + '/' + r.archivo);
};
for (const r of kit.recursos) sacar(r, 'tipografias');
for (const r of kit.referencias) sacar(r, 'referencias');
fs.writeFileSync('flyers.mjs', kit.generador.flyers_mjs);
fs.writeFileSync('datos.json', kit.ejemplo.datos_json);
console.log('Listo. Pon tus fotos en fotos/ y corre:  node flyers.mjs datos.json');
console.log('Antes de escribir nada, MIRA las seis imagenes de referencias/.');
